command:
$ErrorActionPreference = 'Stop'
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$sha='6564165c14ca6dc561a8591ab7a9b696a864b8f6'
$ref='refs/remotes/origin/feat/search-v3-indexed-extension'
$working=Join-Path $env:RUNNER_TEMP 'fly-indexed-extension-release-6564165c'
if(Test-Path -LiteralPath $working){throw 'Reserved worktree already exists'}
Set-Location -LiteralPath $repo
& git fetch origin feat/search-v3-indexed-extension --no-tags
if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
$observed=(& git rev-parse $ref).Trim()
if($LASTEXITCODE -ne 0 -or $observed -ne $sha){throw 'Candidate ref mismatch'}
try {
  & git worktree add --detach $working $sha
  if($LASTEXITCODE -ne 0){throw 'Candidate worktree failed'}
  Set-Location -LiteralPath $working
  & python -X utf8 -m py_compile tests/winui/test_indexed_search_contract.py tests/winui/test_indexed_search_native.py tests/winui/test_indexed_search_gui.py tests/winui/m19/test_native.py
  if($LASTEXITCODE -ne 0){throw 'PYTHON_SYNTAX_FAIL'}
  & python -X utf8 -m unittest tests/winui/test_indexed_search_contract.py
  if($LASTEXITCODE -ne 0){throw 'INDEXED_EXTENSION_CONTRACT_FAIL'}
  Write-Host 'INDEXED_EXTENSION_CONTRACT=PASS'
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw 'INDEXED_EXTENSION_PRODUCT_BUILD_FAIL'}
  Write-Host 'INDEXED_EXTENSION_PRODUCT_BUILD=PASS'
  & cmd.exe /c tests\winui\m19\build.cmd Release
  if($LASTEXITCODE -ne 0){throw 'INDEXED_EXTENSION_NATIVE_BUILD_FAIL'}
  Write-Host 'INDEXED_EXTENSION_NATIVE_BUILD=PASS'
  $env:FLY_M19_CONFIG='Release'
  & python -X utf8 tests/winui/m19/test_native.py
  if($LASTEXITCODE -ne 0){throw 'INDEXED_EXTENSION_NATIVE_FIXTURE_FAIL'}
  Write-Host 'INDEXED_EXTENSION_NATIVE_FIXTURE=PASS'
  & python -X utf8 tests/winui/test_indexed_search_native.py --configuration Release
  if($LASTEXITCODE -ne 0){throw 'INDEXED_EXTENSION_SYSTEMINDEX_FAIL'}
  Write-Host 'INDEXED_EXTENSION_SYSTEMINDEX=PASS'
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture after
  if($LASTEXITCODE -ne 0){throw 'INDEXED_EXTENSION_GUI_FAIL'}
  Write-Host 'INDEXED_EXTENSION_GUI=PASS'
  Write-Host 'INDEXED_EXTENSION_FOCUSED_ACCEPTANCE=PASS'
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $working){
    & git worktree remove --force $working
    if($LASTEXITCODE -ne 0){Write-Host 'CANDIDATE_WORKTREE_CLEANUP=FAIL'}
  }
  & git worktree prune
}
